// Read the AI's follow-up text; fall back to a safe template if needed.
const rows = $('Select Follow-ups').all();
return $input.all().map((item, i) => {
  const r = rows[i].json;
  let body = '';
  const match = String(item.json.text || '').match(/\{[\s\S]*\}/);
  if (match) { try { body = String(JSON.parse(match[0]).body || '').trim(); } catch (e) { /* fallback */ } }
  const recruiterFirst = String(r.recruiter_name || '').split(' ')[0] || r.recruiter_name;
  if (!body) {
    body = r.is_final === 'yes'
      ? `Hi ${r.first_name},\n\nI don't want to fill your inbox, so this is my last note about the ${r.job_title} role. If the timing isn't right, no problem at all; just reply any time if your situation changes.\n\nBest,\n${recruiterFirst}\n${r.agency}`
      : `Hi ${r.first_name},\n\nJust checking whether you saw my note about the ${r.job_title} opening. Happy to share details or set up a quick call if you're interested.\n\nBest,\n${recruiterFirst}\n${r.agency}`;
  }
  const subj = String(r.original_subject || r.job_title || 'Following up');
  return { json: { ...r, body, subject: /^re:/i.test(subj) ? subj : `Re: ${subj}` } };
});

// Only used when FOLLOWUP_MODE is 'send': passes each new draft on to be sent.
if ($('Settings').first().json.FOLLOWUP_MODE !== 'send') return [];
return $input.all().map((i) => ({ json: { draft_id: i.json.id } }));

// Record each follow-up and schedule the next one (or the final wait).
const S = $('Settings').first().json;
const today = new Intl.DateTimeFormat('en-CA', { timeZone: S.TIMEZONE }).format(new Date());
const addDays = (ymd, n) => { const d = new Date(ymd + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + Number(n || 0)); return d.toISOString().slice(0, 10); };
const gaps = S.FOLLOWUP_GAPS_DAYS;
return $('Parse Follow-ups').all().map((i) => {
  const r = i.json;
  const n = r.followup_number;
  const next = n < gaps.length ? addDays(today, gaps[n]) : addDays(today, S.FINAL_WAIT_DAYS);
  return {
    json: {
      ...r.updates,
      followups_sent: String(n),
      last_touch_date: today,
      next_followup_due: next,
      notes: S.FOLLOWUP_MODE === 'send' ? `Follow-up ${n} sent` : `Follow-up ${n} drafted for review`,
    },
  };
});

// Status changes that don't involve writing a follow-up
// (sent detected, replied, bounced, completed, stopped).
return $input.all()
  .filter((i) => i.json.action !== 'followup' && i.json.event)
  .map((i) => ({ json: i.json.updates }));

// Keep the ATS in sync: mark candidates who replied or whose email bounced.
const S = $('Settings').first().json;
const today = new Intl.DateTimeFormat('en-CA', { timeZone: S.TIMEZONE }).format(new Date());
return $input.all()
  .filter((i) => ['replied', 'bounced'].includes(i.json.event))
  .map((i) => ({
    json: i.json.event === 'replied'
      ? { candidate_id: i.json.candidate_id, status: 'Responded', last_contacted: today }
      : { candidate_id: i.json.candidate_id, status: 'Email bounced' },
  }));

// One short morning email per recruiter: replies first, then follow-ups, then closed sequences.
const S = $('Settings').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j.event || j.action === 'followup');
if (!items.length) return [];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const groups = {};
for (const j of items) {
  const key = j.recruiter_email || 'unknown';
  (groups[key] = groups[key] || []).push(j);
}

return Object.entries(groups).map(([to, list]) => {
  const replied = list.filter((j) => j.event === 'replied');
  const fups = list.filter((j) => j.action === 'followup');
  const started = list.filter((j) => j.event === 'sent_detected');
  const closed = list.filter((j) => ['completed', 'stopped', 'bounced'].includes(j.event));
  const first = String(list[0].recruiter_name || '').split(' ')[0] || 'there';
  const section = (title, rows) => rows.length ? `<h3 style="color:#1F3A5F;margin:18px 0 6px">${title}</h3><ul style="margin-top:0">${rows.join('')}</ul>` : '';

  const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
<p>Good morning ${esc(first)},</p>
<p>Here's today's update on your candidate outreach.</p>
${section(`Replies: call these people first (${replied.length})`, replied.map((j) =>
  `<li><b>${esc(j.candidate_name)}</b> replied about <b>${esc(j.job_title)}</b>${j.reply_snippet ? `: <i>"${esc(j.reply_snippet)}"</i>` : ''}</li>`))}
${section(`Follow-ups (${fups.length})`, fups.map((j) =>
  `<li>${esc(j.candidate_name)} (${esc(j.job_title)}): follow-up ${j.followup_number} ${S.FOLLOWUP_MODE === 'send' ? 'sent' : 'is waiting in your Gmail drafts'}</li>`))}
${section(`Emails you sent, now being followed up (${started.length})`, started.map((j) =>
  `<li>${esc(j.candidate_name)} (${esc(j.job_title)})</li>`))}
${section(`Closed (${closed.length})`, closed.map((j) =>
  `<li>${esc(j.candidate_name)} (${esc(j.job_title)}): ${esc(j.updates.status)}</li>`))}
${S.FOLLOWUP_MODE === 'send' ? '' : '<p>Please review and send the follow-up drafts in Gmail.</p>'}
</div>`;

  const parts = [];
  if (replied.length) parts.push(`${replied.length} ${replied.length === 1 ? 'reply' : 'replies'}`);
  if (fups.length) parts.push(`${fups.length} follow-up${fups.length === 1 ? '' : 's'}`);
  if (!parts.length) parts.push('status changes');
  return { json: { to, subject: `Outreach update: ${parts.join(', ')}`, html } };
});

// One Run_Log row per daily check (used by the monthly report).
const S = $('Settings').first().json;
const all = $input.all().map((i) => i.json);
const count = (e) => String(all.filter((j) => j.event === e).length);
const runDate = new Intl.DateTimeFormat('sv-SE', { timeZone: S.TIMEZONE, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date());
return [{
  json: {
    run_date: runDate,
    workflow: 'Follow-up check',
    active_sequences: String(all.length),
    sent_detected: count('sent_detected'),
    followups: String(all.filter((j) => j.action === 'followup').length),
    replies: count('replied'),
    completed: count('completed'),
    stopped: count('stopped'),
    bounced: count('bounced'),
    notes: `Follow-up mode: ${S.FOLLOWUP_MODE}`,
  },
}];
